export function createLargeAeroReverseMovementCompassArt(): SVGGElement {
    return createSvgGroup(MOVEMENT_COMPASS_MARKUP, 'reverse-sheet movement compass');
}

export function createLargeAeroAdvancedMovementReferenceArt(): SVGGElement {
    return createSvgGroup(ADVANCED_MOVEMENT_MARKUP, 'advanced-movement reference');
}

export function createLargeAeroVelocityRecordArt(): SVGGElement {
    return createSvgGroup(VELOCITY_RECORD_MARKUP, 'velocity record');
}

function createSvgGroup(markup: string, label: string): SVGGElement {
    const parsed = new DOMParser().parseFromString(
        `<svg xmlns="${SVG_NS}">${markup}</svg>`,
        'image/svg+xml',
    );
    const source = parsed.documentElement.firstElementChild;
    if (source === null || source.tagName.toLowerCase() !== 'g') {
        throw new Error(`Unable to create the ${label}`);
    }
    return document.importNode(source, true) as SVGGElement;
}
